/* Lens by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
:scope { grid-template-columns:minmax(0,1fr) 300px; padding:24px; gap:32px; }
.ip-hero { grid-column:2; grid-row:1; text-align:center; }
.ip-hero .ip-header { text-align:center; }
.ip-hero .ip-banner { height:160px; }
.page-blocks { grid-column:1; }
.ip-footer { grid-column:1; }
.ip-title { letter-spacing:-.04em; }
.ip-navigation { align-items:center; }
.ip-block { padding-block:16px; }
@media(max-width:760px) { :scope { display:block; padding:20px; } .ip-hero { text-align:left; } .ip-hero .ip-header { text-align:left; } .ip-navigation { align-items:flex-start; } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
